const lessons=[{"sentences":[{"speaker":"A","text":"Sarah we need to update the schedule for the regional marketing workshop tomorrow morning.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.26275},{"speaker":"B","text":"I thought the session started at nine because that is what the original email said.","position":2,"audioStartSeconds":5.46275,"audioEndSeconds":10.454875},{"speaker":"A","text":"Actually management moved it to ten because the keynote speaker has a delayed flight.","position":3,"audioStartSeconds":10.654875,"audioEndSeconds":15.874708333333333},{"speaker":"B","text":"That gives us an extra hour to finish reviewing the presentation slides.","position":4,"audioStartSeconds":16.074708333333334,"audioEndSeconds":20.907958333333333},{"speaker":"A","text":"Please notify all attendees about this change before lunch.","position":5,"audioStartSeconds":21.107958333333332,"audioEndSeconds":25.231666666666666},{"speaker":"B","text":"I will send a quick group message right now.","position":6,"audioStartSeconds":25.43166666666667,"audioEndSeconds":28.511541666666666},{"speaker":"A","text":"Mark do you have a quick moment to look at the new company website layout?","role":"section-start","position":7,"audioStartSeconds":33.511541666666666,"audioEndSeconds":37.91875},{"speaker":"B","text":"I am quite busy with financial reports today unless it is very urgent.","position":8,"audioStartSeconds":38.11875,"audioEndSeconds":42.88679166666667},{"speaker":"A","text":"We found a broken link on the careers page that needs fixing.","position":9,"audioStartSeconds":43.08679166666667,"audioEndSeconds":47.26204166666667},{"speaker":"B","text":"If it involves the careers section I can check that specific page this afternoon.","position":10,"audioStartSeconds":47.462041666666664,"audioEndSeconds":52.578041666666664},{"speaker":"A","text":"Thank you because applicants might complain if they cannot submit their resumes.","position":11,"audioStartSeconds":52.77804166666667,"audioEndSeconds":57.735},{"speaker":"B","text":"I will inspect it immediately after my current task finishes.","position":12,"audioStartSeconds":57.935,"audioEndSeconds":62.24154166666667}],"questions":[{"prompt":"What event are the speakers discussing in the first conversation?","options":["A regional marketing workshop.","A financial training seminar.","A web design conference."],"answer":"A","evidenceSentence":1,"evidence":"regional marketing workshop","explanation":"Người nói A nhắc trực tiếp đến 'regional marketing workshop'."},{"prompt":"Why was the schedule changed?","options":["The room was double booked.","The keynote speaker has a delayed flight.","The manager forgot the original time."],"answer":"B","evidenceSentence":3,"evidence":"keynote speaker has a delayed flight","explanation":"Lý do thay đổi lịch trình là chuyến bay của diễn giả chính bị hoãn."},{"prompt":"What does speaker B agree to do next?","options":["Call the airline.","Send a group message about the change.","Print new presentation handouts."],"answer":"B","evidenceSentence":6,"evidence":"send a quick group message","explanation":"Speaker B đồng ý gửi tin nhắn nhóm để thông báo sự thay đổi."},{"prompt":"What problem does speaker A mention in the second conversation?","options":["A broken link on the careers page.","An outdated financial report.","A missing password for the system."],"answer":"A","evidenceSentence":9,"evidence":"broken link on the careers page","explanation":"Người nói A phát hiện ra một liên kết bị hỏng trên trang tuyển dụng."},{"prompt":"When will speaker B check the page?","options":["Tomorrow morning.","This afternoon.","Next week."],"answer":"B","evidenceSentence":10,"evidence":"this afternoon","explanation":"Speaker B cho biết sẽ kiểm tra trang đó vào chiều nay."},{"prompt":"Why is fixing the page important according to speaker A?","options":["Investors want to read news.","Applicants might not submit resumes.","Management requires daily updates."],"answer":"B","evidenceSentence":11,"evidence":"applicants might complain if they cannot submit their resumes","explanation":"Việc sửa liên kết rất quan trọng vì ứng viên có thể không nộp được hồ sơ."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
